'use client';

import { useMemo } from 'react';
import { MARCO_PANEL_TASKS_PAGE_SIZE } from '../constants';
import { extractMarcoTasksFromBoard, sanitizeCrmRqlLiteral } from '../utils';
import { useCrmBoard } from './use-crm-board';

/**
 * Tarefas completas de UM marco — usado pela árvore do painel.
 *
 * `GET /api/crm/tasks/` é global e paginada: as tarefas de um marco específico
 * só caem na página 1 quando algum filtro (a busca por ativo, tipicamente)
 * reduz bastante o resultado, então a lista base não serve como fonte aqui.
 * O board filtrado por `milestone_id` devolve o marco com as tarefas aninhadas
 * em uma chamada só — ver crm_marcos_tasks_rql_frontend.md.
 */
export function useCrmMarcoTasks(marcoId: string | null | undefined, enabled = true) {
    const boardRql = useMemo(() => {
        const milestoneId = sanitizeCrmRqlLiteral(marcoId ?? '');
        return milestoneId ? `eq(milestone_id,${milestoneId})` : undefined;
    }, [marcoId]);

    const boardQuery = useCrmBoard(
        {
            page: 1,
            pageSize: MARCO_PANEL_TASKS_PAGE_SIZE,
            includeArchived: true,
            query: boardRql,
        },
        { enabled: enabled && !!boardRql },
    );

    // `keepPreviousData` segura o board do marco anterior enquanto o novo carrega.
    const tasks = useMemo(() => {
        if (!marcoId || boardQuery.isPlaceholderData) return [];
        const items = boardQuery.data?.results.items;
        return items ? extractMarcoTasksFromBoard(items, marcoId) : [];
    }, [marcoId, boardQuery.data, boardQuery.isPlaceholderData]);

    return {
        tasks,
        isLoading: enabled && !!boardRql && boardQuery.isFetching,
    };
}

