'use client';

import { keepPreviousData, useInfiniteQuery, useQuery } from '@tanstack/react-query';
import { useMemo } from 'react';
import { QueryKeys } from '@/constants/query-keys';
import { useUserInfoStore } from '@/store/userInfo';
import { PAGE_SIZE, CRM_MARCOS_RESUMIDO_STALE_MS } from '../constants';
import {
    fetchCrmMarcosPage,
    fetchCrmMarco,
    fetchCrmMarcosResumido,
    fetchCrmMarcosResumidoPage,
} from '../services';
import type { CrmMarcoResumidoParams } from '../services';
import type { CrmMarcoListParams } from '../types';
import { useCrmUiStore } from '../store/use-crm-ui-store';
import { sanitizeCrmRqlLiteral } from '../utils';

export function buildCrmMarcoListParams(
    filters: ReturnType<typeof useCrmUiStore.getState>['filters'],
): CrmMarcoListParams {
    const credor = sanitizeCrmRqlLiteral(filters.marcoCredor);
    return {
        sectorId: filters.sectorId,
        search: filters.search || undefined,
        assigneeId: filters.marcoAssigneeId || undefined,
        origemTipo: filters.marcoOrigemTipo,
        credor: credor || undefined,
        emLitigio: filters.marcoEmLitigio,
        hasTasks: filters.marcoHasTasks,
        dueFase: filters.marcoDueFase,
        // As telas do CRM renderizam as tarefas do marco (preview do card,
        // linha da aba Tudo), então a listagem sempre pede o expand.
        expandTasks: true,
    };
}

export function useCrmMarcos(params?: CrmMarcoListParams) {
    const userSessionData = useUserInfoStore((state) => state.data);
    const filters = useCrmUiStore((state) => state.filters);
    const marcoListParams = params ?? buildCrmMarcoListParams(filters);

    return useQuery({
        queryKey: [QueryKeys.uniflowCrm.marcos, 'page', marcoListParams, 1, PAGE_SIZE],
        queryFn: () => fetchCrmMarcosPage(marcoListParams, 1, PAGE_SIZE),
        select: (paginatedResponse) => paginatedResponse.results,
        enabled: !!userSessionData,
        placeholderData: keepPreviousData,
    });
}

export function useCrmMarcosPage(
    params: CrmMarcoListParams | undefined,
    page: number,
    pageSize = PAGE_SIZE,
    options?: { enabled?: boolean },
) {
    const userSessionData = useUserInfoStore((state) => state.data);
    const filters = useCrmUiStore((state) => state.filters);
    const marcoListParams = params ?? buildCrmMarcoListParams(filters);

    return useQuery({
        queryKey: [QueryKeys.uniflowCrm.marcos, 'page', marcoListParams, page, pageSize],
        queryFn: () => fetchCrmMarcosPage(marcoListParams, page, pageSize),
        enabled: (options?.enabled ?? true) && !!userSessionData,
        placeholderData: keepPreviousData,
    });
}

export function useCrmMarcosResumido(enabled = true) {
    const userSessionData = useUserInfoStore((state) => state.data);

    return useQuery({
        queryKey: [QueryKeys.uniflowCrm.marcos, 'resumido'],
        queryFn: fetchCrmMarcosResumido,
        enabled: enabled && !!userSessionData,
        staleTime: CRM_MARCOS_RESUMIDO_STALE_MS,
    });
}

/**
 * Busca paginada do /resumido/ para comboboxes: origem filtrada por RQL e texto
 * repassado ao `search` do backend.
 *
 * A rota devolve 10 itens por página, então o filtro não pode ser client-side —
 * cada termo digitado é uma nova consulta. Passe `search` já debounced.
 */
export function useCrmMarcosResumidoBusca({
    search = '',
    origemTipos,
    enabled = true,
}: CrmMarcoResumidoParams & { enabled?: boolean } = {}) {
    const userSessionData = useUserInfoStore((state) => state.data);
    const term = search.trim();
    // `origemTipos` costuma vir como literal inline no chamador — serializa pra
    // não trocar a queryKey (e refetchar) a cada render.
    const origemTiposKey = origemTipos?.join(',') ?? '';

    const query = useInfiniteQuery({
        queryKey: [QueryKeys.uniflowCrm.marcos, 'resumido', 'busca', origemTiposKey, term],
        queryFn: ({ pageParam }) =>
            fetchCrmMarcosResumidoPage({ search: term, origemTipos }, pageParam),
        initialPageParam: 1,
        getNextPageParam: (lastPage, allPages) => (lastPage.next ? allPages.length + 1 : undefined),
        enabled: enabled && !!userSessionData,
        placeholderData: keepPreviousData,
        staleTime: CRM_MARCOS_RESUMIDO_STALE_MS,
    });

    const marcos = useMemo(
        () => query.data?.pages.flatMap((page) => page.results) ?? [],
        [query.data],
    );

    return {
        marcos,
        total: query.data?.pages[0]?.count ?? 0,
        isLoading: query.isLoading,
        isFetching: query.isFetching,
        hasNextPage: query.hasNextPage,
        isFetchingNextPage: query.isFetchingNextPage,
        fetchNextPage: query.fetchNextPage,
    };
}

export function useCrmMarco(marcoId: string | null | undefined, enabled: boolean) {
    const userSessionData = useUserInfoStore((state) => state.data);

    return useQuery({
        queryKey: [QueryKeys.uniflowCrm.marcos, 'byId', marcoId],
        queryFn: () => fetchCrmMarco(marcoId as string),
        enabled: enabled && !!marcoId && !!userSessionData,
    });
}

