'use client';

import { useMemo } from 'react';
import { keepPreviousData, useQuery } from '@tanstack/react-query';
import { QueryKeys } from '@/constants/query-keys';
import { useUserInfoStore } from '@/store/userInfo';
import { PAGE_SIZE } from '../constants';
import { fetchCrmTasksPage, fetchCrmTask, fetchCrmTasksCalendar } from '../services';
import type { CrmTaskListParams, TaskStatus } from '../types';
import { useCrmUiStore } from '../store/use-crm-ui-store';
import { useCrmUsers } from './use-crm-lookups';
import { sanitizeCrmRqlLiteral } from '../utils';

export function buildCrmTaskListParams(
    filters: ReturnType<typeof useCrmUiStore.getState>['filters'],
): CrmTaskListParams {
    const credor = sanitizeCrmRqlLiteral(filters.marcoCredor);
    return {
        sectorId: filters.sectorId,
        status: filters.status,
        priority: filters.priority,
        assigneeId: filters.assigneeId,
        marcoId: filters.marcoId,
        search: filters.search || undefined,
        origemTipo: filters.marcoOrigemTipo,
        credor: credor || undefined,
        emLitigio: filters.marcoEmLitigio,
        hasMarco: filters.taskHasMarco,
    };
}

export function useCrmTasks(params?: CrmTaskListParams) {
    const userSessionData = useUserInfoStore((state) => state.data);
    const filters = useCrmUiStore((state) => state.filters);
    const taskListParams = params ?? buildCrmTaskListParams(filters);

    return useQuery({
        queryKey: [QueryKeys.uniflowCrm.tasks, 'page', taskListParams, 1, PAGE_SIZE],
        queryFn: () => fetchCrmTasksPage(taskListParams, 1, PAGE_SIZE),
        select: (paginatedResponse) => paginatedResponse.results,
        enabled: !!userSessionData,
        placeholderData: keepPreviousData,
    });
}

export function useCrmTasksPage(
    params: CrmTaskListParams | undefined,
    page: number,
    pageSize = PAGE_SIZE,
    options?: { enabled?: boolean },
) {
    const userSessionData = useUserInfoStore((state) => state.data);
    const filters = useCrmUiStore((state) => state.filters);
    const taskListParams = params ?? buildCrmTaskListParams(filters);

    return useQuery({
        queryKey: [QueryKeys.uniflowCrm.tasks, 'page', taskListParams, page, pageSize],
        queryFn: () => fetchCrmTasksPage(taskListParams, page, pageSize),
        enabled: (options?.enabled ?? true) && !!userSessionData,
        placeholderData: keepPreviousData,
    });
}

export function useCrmTask(taskId: string | null | undefined, enabled: boolean) {
    const userSessionData = useUserInfoStore((state) => state.data);

    return useQuery({
        queryKey: [QueryKeys.uniflowCrm.tasks, 'byId', taskId],
        queryFn: () => fetchCrmTask(taskId as string),
        enabled: enabled && !!taskId && !!userSessionData,
    });
}

/** Query key canônica do calendário — usar em prefetch e no hook. */
export function crmTasksCalendarQueryKey(
    sectorId: string | null | undefined,
    memberIds: number[],
    status?: TaskStatus,
    excludeStatuses?: TaskStatus[],
    ordering?: string | null,
    hasMarco?: boolean | null,
) {
    const excludeKey = excludeStatuses?.length
        ? [...excludeStatuses].sort().join(',')
        : undefined;
    return [
        QueryKeys.uniflowCrm.tasks,
        'calendar',
        sectorId,
        memberIds,
        status,
        excludeKey,
        ordering ?? null,
        hasMarco ?? null,
    ] as const;
}

/**
 * Tasks do ano vigente exibidas no calendário — GET /api/crm/tasks/calendar/
 * (não paginado, ancorado em `prazo_fatal`). Nem `ano` nem `mes` são
 * enviados — o backend assume o ano corrente e retorna tudo de uma vez, então
 * navegar entre meses não refaz a chamada. Filtra por setor/membro só quando
 * os próprios popovers do CalendarView os selecionam (`filters.sectorId` /
 * `filters.filterPersons`, este último traduzido de nome → id via
 * `useCrmUsers`); os demais filtros da FilterBar (status, prioridade, busca,
 * responsável avulso) não têm efeito aqui — o calendário usa só os filtros
 * que o endpoint documenta, mais o vínculo com marco (`filters.taskHasMarco`,
 * RQL `has_marco` — crm_rql_has_marco.md). `status` / `excludeStatuses` filtram a RQL
 * (`eq` na aba concluídas; `ne` na aba pendentes). `ordering` (ex. `prioridade`)
 * é query param Django separado.
 */
export function useCrmTasksCalendar(options?: {
    enabled?: boolean;
    status?: TaskStatus;
    excludeStatuses?: TaskStatus[];
    ordering?: string | null;
}) {
    const userSessionData = useUserInfoStore((state) => state.data);
    const sectorId = useCrmUiStore((state) => state.filters.sectorId);
    const filterPersons = useCrmUiStore((state) => state.filters.filterPersons);
    const hasMarco = useCrmUiStore((state) => state.filters.taskHasMarco);
    const { data: allUsers = [] } = useCrmUsers(sectorId);
    const status = options?.status;
    const excludeStatuses = options?.excludeStatuses;
    const ordering = options?.ordering ?? null;

    const memberIds = useMemo(() => {
        if (filterPersons.length === 0) return [];
        const idByName = new Map(allUsers.map((user) => [user.nome, user.id]));
        return filterPersons.reduce<number[]>((ids, name) => {
            const id = idByName.get(name);
            if (id !== undefined) ids.push(id);
            return ids;
        }, []);
    }, [filterPersons, allUsers]);

    return useQuery({
        queryKey: crmTasksCalendarQueryKey(
            sectorId,
            memberIds,
            status,
            excludeStatuses,
            ordering,
            hasMarco,
        ),
        queryFn: () =>
            fetchCrmTasksCalendar({
                sectorId,
                memberIds,
                status,
                excludeStatuses,
                ordering,
                hasMarco,
            }),
        select: (response) => response.results,
        enabled: (options?.enabled ?? true) && !!userSessionData,
        placeholderData: keepPreviousData,
    });
}

