51	function mapCrmUserToMini(user: CrmUser | null | undefined): CrmUserMini | null {
52	    if (!user) return null;
53	    return {
54	        id: user.id,
55	        username: user.username,
56	        email: user.email ?? '',
57	        nome: user.nome,
58	        avatarUrl: user.avatarUrl ?? null,
59	        sectorId: user.sectorId ?? null,
60	        teamId: user.teamId ?? null,
61	        cargo: '',
62	    };
63	}
64	
65	function mapCrmTaskToResumo(task: CrmTask, fallbackMarcoId: string | null): ProcessoTarefaResumo {
66	    return {
67	        id: task.id,
68	        resumo: task.resumo,
69	        status: task.status,
70	        prioridade: task.prioridade,
71	        prazo_fatal: task.prazo_fatal ?? null,
72	        data_inicio: task.data_inicio ?? null,
73	        data_alerta: task.data_alerta ?? null,
74	        marcoId: task.marcoId ?? fallbackMarcoId,
75	        responsavel: mapCrmUserToMini(task.responsavel_detail),
76	        criado_por: mapCrmUserToMini(task.criado_por),
77	        created_at: task.created_at,
78	    };
79	}
80	
81	function extractTasksFromBoard(
82	    items: CrmBoardStreamItem[],
83	    marcoId: string,
84	): ProcessoTarefaResumo[] {
85	    const byId = new Map<string, ProcessoTarefaResumo>();
86	
87	    for (const item of items) {
88	        if (item.type === 'milestone' && item.id === marcoId) {
89	            for (const task of item.tasks) {
90	                byId.set(task.id, mapCrmTaskToResumo(task, marcoId));
91	            }
92	            continue;
93	        }
94	        if (item.type === 'task' && item.marcoId === marcoId) {
95	            byId.set(item.id, mapCrmTaskToResumo(item, marcoId));
96	        }
97	    }
98	
99	    return Array.from(byId.values());
100	}
101	
102	export function TasksTab({ owner, variant = 'default' }: TasksTabProps) {
103	    const isRail = variant === 'rail';
104	    const isFromDasi = getTenantFromUrl() === Tenants.DASI;
105	    const isProcesso = owner.kind === 'processo';
106	
107	    const [isCreateOpen, setIsCreateOpen] = useState(false);
108	    const [includeArchivedTasks, setIncludeArchivedTasks] = useState(false);
109	    const openTaskPanel = useCrmUiStore((state) => state.openTaskPanel);
110	    const openMarcoPanel = useCrmUiStore((state) => state.openMarcoPanel);
111	
112	    const queryClient = useQueryClient();
113	
114	    const processoQuery = useQuery(getProcessoVinculadoByIdQuery(isProcesso ? owner.id : null));
115	    const posQuery = useQuery(getPostPurchaseByIdQuery(isProcesso ? null : owner.id));
116	
117	    const { data, isLoading, isFetching, isError, refetch } = isProcesso ? processoQuery : posQuery;
118	
119	    const toggleTarefaStatus = useMutation({
120	        mutationFn: ({ id, nextStatus }: { id: string; nextStatus: TaskStatus }) =>
121	            updateCrmTaskStatus(id, nextStatus),
122	        // Mesmo patch otimista do toggle do CRM (use-crm-task-mutations.ts): garante que o
123	        // painel do marco (que lê o cache de tarefas do CRM) reflita a mudança na hora,
124	        // sem depender do timing do invalidate/refetch abaixo.
125	        onMutate: async ({ id, nextStatus }) => {
126	            await queryClient.cancelQueries({ queryKey: [QueryKeys.uniflowCrm.tasks] });
127	            const snapshot = snapshotCrmTaskRelatedQueries();
128	            applyOptimisticTaskStatus(id, nextStatus);
129	            return { snapshot };
130	        },
131	        onError: (_error, _vars, context) => {
132	            if (context?.snapshot) restoreCrmTaskRelatedQueries(context.snapshot);
133	        },
134	        // invalidateUniflowCrmTaskDomain já cobre processos/pós-aquisição (ver invalidate.ts).
135	        onSettled: () => {
136	            void invalidateUniflowCrmTaskDomain();
137	        },
138	    });
139	
140	    const handleToggleTarefaDone = (tarefa: ProcessoTarefaResumo) => {
141	        const nextStatus: TaskStatus = tarefa.status === 'CONCLUIDO' ? 'NAO_INICIADA' : 'CONCLUIDO';
142	        toggleTarefaStatus.mutate({ id: tarefa.id, nextStatus });
143	    };
144	
145	    const detailTarefas = useMemo(() => data?.tarefas ?? [], [data?.tarefas]);
146	    const marcoIndisponivel = Boolean(data?.tarefasMarcoIndisponivel);
147	    // O detalhe do Pós-Aquisição/Processo já vem com o marco resolvido pelo backend
148	    // (todo registro tem um) — não depende mais de existir alguma tarefa criada.
149	    const marcoId = data?.marcoId ?? null;
150	    const canOpenCrmPanel = !isFromDasi && !marcoIndisponivel;
151	    const canFetchArchived = Boolean(marcoId) && !marcoIndisponivel;
152	
153	    const archivedBoardQuery = sanitizeCrmRqlLiteral(marcoId ?? '');
154	    const boardQuery = useCrmBoard(
155	        {
156	            page: 1,
157	            pageSize: TASKS_TAB_ARCHIVED_BOARD_PAGE_SIZE,
158	            includeArchived: true,
159	            query: archivedBoardQuery ? `eq(milestone_id,${archivedBoardQuery})` : undefined,
160	        },
161	        { enabled: includeArchivedTasks && canFetchArchived },
162	    );
163	
164	    const archivedTarefas = useMemo(() => {
165	        if (!marcoId || !boardQuery.data) return null;
166	        return extractTasksFromBoard(boardQuery.data.results.items ?? [], marcoId);
167	    }, [marcoId, boardQuery.data]);
168	
169	    // Com includeArchived: usa o board quando há data (inclusive lista vazia).
170	    // Não volta ao detalhe no refetch — evita flicker sumindo arquivadas.
171	    const tarefas = useMemo(() => {
172	        if (!includeArchivedTasks) return detailTarefas;
173	        if (boardQuery.isError) return detailTarefas;
174	        if (archivedTarefas === null) return detailTarefas;
175	        return archivedTarefas;
176	    }, [includeArchivedTasks, detailTarefas, archivedTarefas, boardQuery.isError]);
177	
178	    const emptyMinHeightStyle = isRail ? undefined : { minHeight: TASKS_TAB_EMPTY_MIN_HEIGHT_PX };
179	    const isListFetching =
180	        isFetching || (includeArchivedTasks && canFetchArchived && boardQuery.isFetching);
181	    const isListLoading =
182	        isLoading ||
183	        (includeArchivedTasks &&
184	            canFetchArchived &&
185	            boardQuery.isLoading &&
186	            archivedTarefas === null);
187	
