'use client';

import { useEffect, useMemo, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { AlertTriangle, Calendar, CheckSquare, Layout, Plus, User } from 'lucide-react';
import { cn } from '@/lib/utils';
import {
    getProcessoVinculadoByIdQuery,
    getPostPurchaseByIdQuery,
} from '@/hooks/queries/post-purchase';
import { QueryKeys } from '@/constants/query-keys';
import { Tenants } from '@/enums/tenants.enum';
import { getTenantFromUrl } from '@/utils/getHostFromUrl';
import { getInitials } from '@/functions/formaters/getInitials';
import dateFormater from '@/functions/formaters/dateFormater';
import { Checkbox } from '@/components/ui/checkbox';
import { TruncatedText } from '@/components/ui/truncated-text';
import { COLORS } from '@/design-system';
import { useCrmUiStore } from '@/app/uniflow/crm/store/use-crm-ui-store';
import { sanitizeCrmRqlLiteral, useCrmBoard } from '@/app/uniflow/crm/hooks/use-crm-board';
import {
    applyOptimisticTaskStatus,
    restoreCrmTaskRelatedQueries,
    snapshotCrmTaskRelatedQueries,
} from '@/app/uniflow/crm/hooks/crm-task-cache';
import { invalidateUniflowCrmTaskDomain } from '@/app/uniflow/crm/hooks';
import { updateCrmTaskStatus } from '@/app/uniflow/crm/services';
import type { CrmBoardStreamItem, CrmTask, CrmUser, TaskStatus } from '@/app/uniflow/crm/types';
import type { CrmUserMini, ProcessoTarefaResumo } from '@/interfaces/IProcessoVinculado';
import { CreateTarefaModal } from './CreateTarefaModal';
import {
    INCLUDE_ARCHIVED_TASKS_LABEL,
    PRIORIDADE_BADGE_CLASSES,
    PRIORIDADE_LABELS,
    STATUS_BADGE_CLASSES,
    STATUS_BADGE_FALLBACK_CLASSES,
    STATUS_LABELS,
    TASKS_TAB_ARCHIVED_BOARD_PAGE_SIZE,
    TASKS_TAB_EMPTY_MIN_HEIGHT_PX,
    type TaskOwner,
} from './tarefa-constants';

export type { TaskOwner };

interface TasksTabProps {
    owner: TaskOwner;
    /** Layout compacto da coluna sticky (fora das tabs do main). */
    variant?: 'default' | 'rail';
}

function mapCrmUserToMini(user: CrmUser | null | undefined): CrmUserMini | null {
    if (!user) return null;
    return {
        id: user.id,
        username: user.username,
        email: user.email ?? '',
        nome: user.nome,
        avatarUrl: user.avatarUrl ?? null,
        sectorId: user.sectorId ?? null,
        teamId: user.teamId ?? null,
        cargo: '',
    };
}

function mapCrmTaskToResumo(task: CrmTask, fallbackMarcoId: string | null): ProcessoTarefaResumo {
    return {
        id: task.id,
        resumo: task.resumo,
        status: task.status,
        prioridade: task.prioridade,
        prazo_fatal: task.prazo_fatal ?? null,
        data_inicio: task.data_inicio ?? null,
        data_alerta: task.data_alerta ?? null,
        marcoId: task.marcoId ?? fallbackMarcoId,
        responsavel: mapCrmUserToMini(task.responsavel_detail),
        criado_por: mapCrmUserToMini(task.criado_por),
        created_at: task.created_at,
    };
}

function extractTasksFromBoard(
    items: CrmBoardStreamItem[],
    marcoId: string,
): ProcessoTarefaResumo[] {
    const byId = new Map<string, ProcessoTarefaResumo>();

    for (const item of items) {
        if (item.type === 'milestone' && item.id === marcoId) {
            for (const task of item.tasks) {
                byId.set(task.id, mapCrmTaskToResumo(task, marcoId));
            }
            continue;
        }
        if (item.type === 'task' && item.marcoId === marcoId) {
            byId.set(item.id, mapCrmTaskToResumo(item, marcoId));
        }
    }

    return Array.from(byId.values());
}

export function TasksTab({ owner, variant = 'default' }: TasksTabProps) {
    const isRail = variant === 'rail';
    const isFromDasi = getTenantFromUrl() === Tenants.DASI;
    const isProcesso = owner.kind === 'processo';

    const [isCreateOpen, setIsCreateOpen] = useState(false);
    const [includeArchivedTasks, setIncludeArchivedTasks] = useState(false);
    const openTaskPanel = useCrmUiStore((state) => state.openTaskPanel);
    const openMarcoPanel = useCrmUiStore((state) => state.openMarcoPanel);

    const queryClient = useQueryClient();

    const processoQuery = useQuery(getProcessoVinculadoByIdQuery(isProcesso ? owner.id : null));
    const posQuery = useQuery(getPostPurchaseByIdQuery(isProcesso ? null : owner.id));

    const { data, isLoading, isFetching, isError, refetch } = isProcesso ? processoQuery : posQuery;

    const toggleTarefaStatus = useMutation({
        mutationFn: ({ id, nextStatus }: { id: string; nextStatus: TaskStatus }) =>
            updateCrmTaskStatus(id, nextStatus),
        // Mesmo patch otimista do toggle do CRM (use-crm-task-mutations.ts): garante que o
        // painel do marco (que lê o cache de tarefas do CRM) reflita a mudança na hora,
        // sem depender do timing do invalidate/refetch abaixo.
        onMutate: async ({ id, nextStatus }) => {
            await queryClient.cancelQueries({ queryKey: [QueryKeys.uniflowCrm.tasks] });
            const snapshot = snapshotCrmTaskRelatedQueries();
            applyOptimisticTaskStatus(id, nextStatus);
            return { snapshot };
        },
        onError: (_error, _vars, context) => {
            if (context?.snapshot) restoreCrmTaskRelatedQueries(context.snapshot);
        },
        // invalidateUniflowCrmTaskDomain já cobre processos/pós-aquisição (ver invalidate.ts).
        onSettled: () => {
            void invalidateUniflowCrmTaskDomain();
        },
    });

    const handleToggleTarefaDone = (tarefa: ProcessoTarefaResumo) => {
        const nextStatus: TaskStatus = tarefa.status === 'CONCLUIDO' ? 'NAO_INICIADA' : 'CONCLUIDO';
        toggleTarefaStatus.mutate({ id: tarefa.id, nextStatus });
    };

    const detailTarefas = useMemo(() => data?.tarefas ?? [], [data?.tarefas]);
    const marcoIndisponivel = Boolean(data?.tarefasMarcoIndisponivel);
    // O detalhe do Pós-Aquisição/Processo já vem com o marco resolvido pelo backend
    // (todo registro tem um) — não depende mais de existir alguma tarefa criada.
    const marcoId = data?.marcoId ?? null;
    const canOpenCrmPanel = !isFromDasi && !marcoIndisponivel;
    const canFetchArchived = Boolean(marcoId) && !marcoIndisponivel;

    const archivedBoardQuery = sanitizeCrmRqlLiteral(marcoId ?? '');
    const boardQuery = useCrmBoard(
        {
            page: 1,
            pageSize: TASKS_TAB_ARCHIVED_BOARD_PAGE_SIZE,
            includeArchived: true,
            query: archivedBoardQuery ? `eq(milestone_id,${archivedBoardQuery})` : undefined,
        },
        { enabled: includeArchivedTasks && canFetchArchived },
    );

    const archivedTarefas = useMemo(() => {
        if (!marcoId || !boardQuery.data) return null;
        return extractTasksFromBoard(boardQuery.data.results.items ?? [], marcoId);
    }, [marcoId, boardQuery.data]);

    // Com includeArchived: usa o board quando há data (inclusive lista vazia).
    // Não volta ao detalhe no refetch — evita flicker sumindo arquivadas.
    const tarefas = useMemo(() => {
        if (!includeArchivedTasks) return detailTarefas;
        if (boardQuery.isError) return detailTarefas;
        if (archivedTarefas === null) return detailTarefas;
        return archivedTarefas;
    }, [includeArchivedTasks, detailTarefas, archivedTarefas, boardQuery.isError]);

    const emptyMinHeightStyle = isRail ? undefined : { minHeight: TASKS_TAB_EMPTY_MIN_HEIGHT_PX };
    const isListFetching =
        isFetching || (includeArchivedTasks && canFetchArchived && boardQuery.isFetching);
    const isListLoading =
        isLoading ||
        (includeArchivedTasks &&
            canFetchArchived &&
            boardQuery.isLoading &&
            archivedTarefas === null);

    const listContent = (
        <>
            {marcoIndisponivel && (
                <div className="flex items-start gap-2 rounded-lg border border-amber-300 bg-amber-50 p-3 text-xs text-amber-800 dark:border-amber-500/30 dark:bg-amber-500/10 dark:text-amber-300">
                    <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
                    <span>
                        Não foi possível resolver o marco CRM deste registro. A criação de tarefas
                        está temporariamente indisponível.
                    </span>
                </div>
            )}

            {includeArchivedTasks && boardQuery.isError && (
                <div className="flex flex-col items-start gap-2 rounded-lg border border-red-200 bg-red-50 p-3 text-xs text-red-700 dark:border-red-500/30 dark:bg-red-500/10 dark:text-red-300">
                    <div className="flex items-start gap-2">
                        <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
                        <span>
                            Não foi possível carregar as tarefas arquivadas. Exibindo apenas as do
                            detalhe.
                        </span>
                    </div>
                    <button
                        type="button"
                        onClick={() => void boardQuery.refetch()}
                        className="ml-6 rounded-lg border border-red-200 bg-white px-3 py-1.5 text-xs font-semibold text-red-700 transition-colors hover:bg-red-100 dark:border-red-500/30 dark:bg-card dark:text-red-300"
                    >
                        Tentar novamente
                    </button>
                </div>
            )}

            <div className={cn('flex flex-col gap-2.5', isRail && 'h-full min-h-0')}>
                {isListLoading ? (
                    <div
                        className={cn(
                            'flex items-center justify-center text-sm',
                            isRail
                                ? 'h-full min-h-[120px] text-celer-muted dark:text-muted-foreground'
                                : 'rounded-2xl border border-dashed border-celer-line bg-celer-paper text-celer-muted dark:border-white/10 dark:bg-celer-graphite dark:text-muted-foreground',
                        )}
                        style={emptyMinHeightStyle}
                    >
                        Carregando tarefas...
                    </div>
                ) : isError ? (
                    <div
                        className={cn(
                            'flex flex-col items-center justify-center gap-3 rounded-2xl border border-dashed border-red-200 bg-celer-paper text-sm text-celer-muted dark:border-red-500/30 dark:bg-celer-graphite dark:text-muted-foreground',
                            isRail && 'h-full min-h-[120px]',
                        )}
                        style={emptyMinHeightStyle}
                    >
                        <AlertTriangle className="h-5 w-5 text-red-500" />
                        <span>Não foi possível carregar as tarefas.</span>
                        <button
                            type="button"
                            onClick={() => void refetch()}
                            className="hover:border-celer-blue/30 rounded-lg border border-celer-line bg-celer-paper px-3 py-1.5 text-xs font-semibold text-celer-strong transition-colors hover:text-celer-blue dark:border-white/10 dark:bg-celer-graphite dark:text-foreground"
                        >
                            Tentar novamente
                        </button>
                    </div>
                ) : tarefas.length === 0 ? (
                    <div
                        className={cn(
                            'flex flex-col items-center justify-center gap-2 text-sm',
                            isRail
                                ? 'h-full min-h-[120px] text-celer-muted dark:text-muted-foreground'
                                : 'rounded-2xl border border-dashed border-celer-line bg-celer-paper text-celer-muted dark:border-white/10 dark:bg-celer-graphite dark:text-muted-foreground',
                        )}
                        style={emptyMinHeightStyle}
                    >
                        <CheckSquare
                            className={cn(
                                isRail
                                    ? 'h-5 w-5 text-celer-muted opacity-80'
                                    : 'h-6 w-6 opacity-30',
                            )}
                        />
                        {isRail ? 'Nenhuma tarefa vinculada.' : 'Nenhuma tarefa criada ainda'}
                    </div>
                ) : (
                    tarefas.map((tarefa) => {
                        const statusBadgeClass =
                            STATUS_BADGE_CLASSES[tarefa.status] ?? STATUS_BADGE_FALLBACK_CLASSES;
                        const prioBadgeClass =
                            PRIORIDADE_BADGE_CLASSES[tarefa.prioridade] ??
                            STATUS_BADGE_FALLBACK_CLASSES;
                        const responsavelNome = tarefa.responsavel?.nome;

                        return (
                            <div
                                key={tarefa.id}
                                role={canOpenCrmPanel ? 'button' : undefined}
                                tabIndex={canOpenCrmPanel ? 0 : undefined}
                                onClick={
                                    canOpenCrmPanel
                                        ? () => openTaskPanel(tarefa.id, tarefa.marcoId)
                                        : undefined
                                }
                                onKeyDown={
                                    canOpenCrmPanel
                                        ? (e) => {
                                              if (e.key === 'Enter' || e.key === ' ') {
                                                  e.preventDefault();
                                                  openTaskPanel(tarefa.id, tarefa.marcoId);
                                              }
                                          }
                                        : undefined
                                }
                                title={
                                    canOpenCrmPanel
                                        ? 'Abrir painel da tarefa (Chat, Histórico, Arquivos)'
                                        : undefined
                                }
                                className={
                                    canOpenCrmPanel
                                        ? 'hover:border-celer-blue/30 dark:hover:border-celer-blue/30 border-celer-line/80 cursor-pointer rounded-[14px] border bg-celer-paper p-4 shadow-celer-rest transition-colors hover:shadow-md dark:border-white/10 dark:bg-celer-graphite dark:shadow-none'
                                        : 'border-celer-line/80 rounded-[14px] border bg-celer-paper p-4 shadow-celer-rest dark:border-white/10 dark:bg-celer-graphite dark:shadow-none'
                                }
                            >
                                <div className="flex items-start justify-between gap-3">
                                    <div className="min-w-0 flex-1">
                                        <TruncatedText
                                            as="h4"
                                            text={tarefa.resumo}
                                            className="line-clamp-2 wrap-break-word text-sm font-semibold leading-tight text-celer-strong dark:text-foreground"
                                        />
                                        <div className="mt-2 flex flex-wrap items-center gap-1.5">
                                            <span
                                                className={`rounded-sm px-1.5 py-0.5 text-[10px] font-semibold ${statusBadgeClass}`}
                                            >
                                                {STATUS_LABELS[tarefa.status] ?? tarefa.status}
                                            </span>
                                            <span
                                                className={`rounded-sm px-1.5 py-0.5 text-[10px] font-semibold ${prioBadgeClass}`}
                                            >
                                                {PRIORIDADE_LABELS[tarefa.prioridade] ??
                                                    tarefa.prioridade}
                                            </span>
                                            {tarefa.prazo_fatal && (
                                                <span className="inline-flex items-center gap-1 text-[10px] text-celer-muted dark:text-muted-foreground">
                                                    <Calendar className="h-3 w-3" />
                                                    {dateFormater(tarefa.prazo_fatal)}
                                                </span>
                                            )}
                                        </div>
                                    </div>

                                    <div className="flex shrink-0 items-center gap-2">
                                        {responsavelNome ? (
                                            <div
                                                className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-celer-panel text-[10px] font-extrabold text-celer-muted dark:bg-muted dark:text-muted-foreground"
                                                title={responsavelNome}
                                            >
                                                {getInitials(responsavelNome)}
                                            </div>
                                        ) : (
                                            <div
                                                className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full border border-dashed border-celer-line text-celer-muted dark:border-white/20"
                                                title="Sem responsável"
                                            >
                                                <User className="h-3.5 w-3.5" />
                                            </div>
                                        )}
                                        {canOpenCrmPanel && (
                                            <Layout className="h-3.5 w-3.5 shrink-0 text-celer-line dark:text-muted-foreground/50" />
                                        )}
                                    </div>
                                </div>

                                {tarefa.criado_por?.nome && (
                                    <p className="mt-2 border-t border-dashed border-celer-line pt-2 text-[10px] text-celer-muted dark:border-white/10 dark:text-muted-foreground">
                                        Criada por {tarefa.criado_por.nome} ·{' '}
                                        {dateFormater(tarefa.created_at)}
                                    </p>
                                )}
                            </div>
                        );
                    })
                )}
            </div>
        </>
    );

    if (isRail) {
        return (
            <div className="flex h-full min-h-0 flex-col gap-2.5">
                {!marcoIndisponivel && (
                    <CreateTarefaModal
                        owner={owner}
                        open={isCreateOpen}
                        onOpenChange={setIsCreateOpen}
                        initialMarcoId={marcoId}
                    />
                )}

                <div className="flex shrink-0 items-center justify-between gap-2">
                    <p className="text-[12px] font-medium text-celer-muted dark:text-muted-foreground">
                        {tarefas.length} {tarefas.length === 1 ? 'tarefa' : 'tarefas'}
                        {isListFetching ? ' · atualizando...' : ''}
                    </p>
                    <label
                        className={cn(
                            'inline-flex items-center gap-1.5 rounded-lg border border-celer-line bg-celer-paper px-2.5 py-1.5 text-[11px] font-medium text-celer-strong dark:border-white/10 dark:bg-celer-graphite dark:text-foreground',
                            canFetchArchived ? 'cursor-pointer' : 'cursor-not-allowed opacity-50',
                        )}
                        title={
                            canFetchArchived
                                ? INCLUDE_ARCHIVED_TASKS_LABEL
                                : 'Marco CRM indisponível para buscar arquivadas'
                        }
                    >
                        <Checkbox
                            checked={includeArchivedTasks}
                            disabled={!canFetchArchived}
                            onCheckedChange={(checked) => setIncludeArchivedTasks(checked === true)}
                            aria-label={INCLUDE_ARCHIVED_TASKS_LABEL}
                        />
                        {INCLUDE_ARCHIVED_TASKS_LABEL}
                    </label>
                </div>

                <div className="dark:bg-celer-ink/50 min-h-0 flex-1 overflow-y-auto rounded-xl bg-celer-panel px-2.5 py-2.5">
                    {listContent}
                </div>

                {canOpenCrmPanel && (
                    <div className="flex shrink-0 gap-2">
                        {marcoId && (
                            <button
                                type="button"
                                onClick={() => openMarcoPanel(marcoId)}
                                className="dark:hover:bg-celer-slate/50 inline-flex h-10 min-w-0 flex-1 items-center justify-center gap-1.5 rounded-lg border border-celer-line bg-celer-paper px-2.5 text-[12px] font-semibold text-celer-strong transition-colors hover:bg-celer-panel dark:border-white/10 dark:bg-celer-graphite dark:text-foreground"
                                title="Abrir painel completo do Marco"
                            >
                                <Layout className="h-3.5 w-3.5 shrink-0" />
                                <span className="truncate">Painel do marco</span>
                            </button>
                        )}
                        <button
                            type="button"
                            onClick={() => setIsCreateOpen(true)}
                            className={cn(
                                'border-celer-blue/40 hover:bg-celer-blue/4 dark:hover:bg-celer-blue/10 inline-flex h-10 min-w-0 flex-1 items-center justify-center gap-1.5 rounded-lg border bg-celer-paper px-2.5 text-[12px] font-semibold text-celer-blue transition-colors dark:bg-celer-graphite',
                                !marcoId && 'flex-[1.1]',
                            )}
                        >
                            <Plus className="h-3.5 w-3.5 shrink-0" strokeWidth={2.5} />
                            <span className="truncate">Nova Tarefa</span>
                        </button>
                    </div>
                )}
            </div>
        );
    }

    return (
        <div className="flex flex-col gap-4">
            <div className="flex flex-wrap items-center justify-between gap-3">
                <div className="flex items-center gap-3">
                    <div className="flex h-8 w-8 items-center justify-center rounded-[7px] bg-[#0891b2]/10">
                        <CheckSquare className="h-4 w-4 text-[#0891b2] dark:text-meta-10" />
                    </div>
                    <div>
                        <h3 className="text-sm font-bold text-title dark:text-card-foreground">
                            Tarefas
                        </h3>
                        <span className="text-xs text-[#888] dark:text-muted-foreground">
                            {tarefas.length} {tarefas.length === 1 ? 'tarefa' : 'tarefas'}
                            {includeArchivedTasks ? ' · com arquivadas' : ''}
                            {isListFetching ? ' · atualizando...' : ''}
                        </span>
                    </div>
                </div>

                <div className="flex flex-wrap items-center gap-2">
                    <label
                        className={`inline-flex items-center gap-2 rounded-lg border border-stroke bg-white px-3 py-2 text-xs font-medium text-title dark:border-border dark:bg-card dark:text-card-foreground ${
                            canFetchArchived ? 'cursor-pointer' : 'cursor-not-allowed opacity-50'
                        }`}
                        title={
                            canFetchArchived
                                ? INCLUDE_ARCHIVED_TASKS_LABEL
                                : 'Marco CRM indisponível para buscar arquivadas'
                        }
                    >
                        <Checkbox
                            checked={includeArchivedTasks}
                            disabled={!canFetchArchived}
                            onCheckedChange={(checked) => setIncludeArchivedTasks(checked === true)}
                            aria-label={INCLUDE_ARCHIVED_TASKS_LABEL}
                        />
                        {INCLUDE_ARCHIVED_TASKS_LABEL}
                    </label>

                    {canOpenCrmPanel && (
                        <>
                            {marcoId && (
                                <button
                                    type="button"
                                    onClick={() => openMarcoPanel(marcoId)}
                                    className="hover:border-app-default/30 hover:bg-app-default/3 dark:hover:bg-app-default/10 inline-flex items-center gap-1.5 rounded-lg border border-stroke bg-white px-3 py-2 text-xs font-semibold text-title shadow-sm transition-colors hover:text-app-default dark:border-border dark:bg-card dark:text-card-foreground"
                                    title="Abrir painel completo do Marco (Chat, Histórico, Arquivos)"
                                >
                                    <Layout className="h-3.5 w-3.5" />
                                    Painel do Marco
                                </button>
                            )}
                            <button
                                type="button"
                                onClick={() => setIsCreateOpen(true)}
                                className="hover:border-app-default/30 hover:bg-app-default/3 dark:hover:bg-app-default/10 inline-flex items-center gap-1.5 rounded-lg border border-stroke bg-white px-3 py-2 text-xs font-semibold text-title shadow-sm transition-colors hover:text-app-default dark:border-border dark:bg-card dark:text-card-foreground"
                            >
                                <Plus className="h-3.5 w-3.5" />
                                Nova tarefa
                            </button>
                        </>
                    )}
                </div>
            </div>

            {!marcoIndisponivel && (
                <CreateTarefaModal
                    owner={owner}
                    open={isCreateOpen}
                    onOpenChange={setIsCreateOpen}
                    initialMarcoId={marcoId}
                />
            )}

            {marcoIndisponivel && (
                <div className="flex items-start gap-2 rounded-lg border border-amber-300 bg-amber-50 p-3 text-xs text-amber-800 dark:border-amber-500/30 dark:bg-amber-500/10 dark:text-amber-300">
                    <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
                    <span>
                        Não foi possível resolver o marco CRM deste registro. A criação de tarefas
                        está temporariamente indisponível.
                    </span>
                </div>
            )}

            {includeArchivedTasks && boardQuery.isError && (
                <div className="flex flex-col items-start gap-2 rounded-lg border border-red-200 bg-red-50 p-3 text-xs text-red-700 dark:border-red-500/30 dark:bg-red-500/10 dark:text-red-300">
                    <div className="flex items-start gap-2">
                        <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
                        <span>
                            Não foi possível carregar as tarefas arquivadas. Exibindo apenas as do
                            detalhe.
                        </span>
                    </div>
                    <button
                        type="button"
                        onClick={() => void boardQuery.refetch()}
                        className="ml-6 rounded-lg border border-red-200 bg-white px-3 py-1.5 text-xs font-semibold text-red-700 transition-colors hover:bg-red-100 dark:border-red-500/30 dark:bg-card dark:text-red-300"
                    >
                        Tentar novamente
                    </button>
                </div>
            )}

            <div className="flex flex-col gap-2.5">
                {isListLoading ? (
                    <div
                        className="flex items-center justify-center rounded-2xl border border-dashed border-slate-200 bg-white text-sm text-slate-500 dark:border-slate-800 dark:bg-card dark:text-slate-400"
                        style={emptyMinHeightStyle}
                    >
                        Carregando tarefas...
                    </div>
                ) : isError ? (
                    <div
                        className="flex flex-col items-center justify-center gap-3 rounded-2xl border border-dashed border-red-200 bg-white text-sm text-slate-600 dark:border-red-500/30 dark:bg-card dark:text-slate-300"
                        style={emptyMinHeightStyle}
                    >
                        <AlertTriangle className="h-5 w-5 text-red-500" />
                        <span>Não foi possível carregar as tarefas.</span>
                        <button
                            type="button"
                            onClick={() => void refetch()}
                            className="hover:border-app-default/30 rounded-lg border border-stroke bg-white px-3 py-1.5 text-xs font-semibold text-title transition-colors hover:text-app-default dark:border-border dark:bg-card dark:text-card-foreground"
                        >
                            Tentar novamente
                        </button>
                    </div>
                ) : tarefas.length === 0 ? (
                    <div
                        className="flex flex-col items-center justify-center gap-2 rounded-2xl border border-dashed border-slate-200 bg-white text-sm text-slate-500 dark:border-slate-800 dark:bg-card dark:text-slate-400"
                        style={emptyMinHeightStyle}
                    >
                        <CheckSquare className="h-6 w-6 opacity-30" />
                        Nenhuma tarefa criada ainda
                    </div>
                ) : (
                    tarefas.map((tarefa) => (
                        <TarefaCard
                            key={tarefa.id}
                            tarefa={tarefa}
                            canOpenCrmPanel={canOpenCrmPanel}
                            onOpenTaskPanel={openTaskPanel}
                            onToggleDone={handleToggleTarefaDone}
                        />
                    ))
                )}
            </div>
        </div>
    );
}

interface TarefaCardProps {
    tarefa: ProcessoTarefaResumo;
    canOpenCrmPanel: boolean;
    onOpenTaskPanel: (taskId: string, marcoId: string | null) => void;
    onToggleDone: (tarefa: ProcessoTarefaResumo) => void;
}

function TarefaCard({ tarefa, canOpenCrmPanel, onOpenTaskPanel, onToggleDone }: TarefaCardProps) {
    const [optimisticDone, setOptimisticDone] = useState<boolean | null>(null);

    useEffect(() => {
        setOptimisticDone(null);
    }, [tarefa.status]);

    const isDone = tarefa.status === 'CONCLUIDO';
    const displayDone = optimisticDone !== null ? optimisticDone : isDone;

    const statusBadgeClass = STATUS_BADGE_CLASSES[tarefa.status] ?? STATUS_BADGE_FALLBACK_CLASSES;
    const prioBadgeClass =
        PRIORIDADE_BADGE_CLASSES[tarefa.prioridade] ?? STATUS_BADGE_FALLBACK_CLASSES;
    const responsavelNome = tarefa.responsavel?.nome;

    function handleToggleDone(e: React.MouseEvent) {
        e.stopPropagation();
        const nextDone = !displayDone;
        setOptimisticDone(nextDone);
        setTimeout(() => onToggleDone(tarefa), 300);
    }

    return (
        <div
            role={canOpenCrmPanel ? 'button' : undefined}
            tabIndex={canOpenCrmPanel ? 0 : undefined}
            onClick={canOpenCrmPanel ? () => onOpenTaskPanel(tarefa.id, tarefa.marcoId) : undefined}
            onKeyDown={
                canOpenCrmPanel
                    ? (e) => {
                          if (e.key === 'Enter' || e.key === ' ') {
                              e.preventDefault();
                              onOpenTaskPanel(tarefa.id, tarefa.marcoId);
                          }
                      }
                    : undefined
            }
            title={
                canOpenCrmPanel ? 'Abrir painel da tarefa (Chat, Histórico, Arquivos)' : undefined
            }
            className={
                canOpenCrmPanel
                    ? 'hover:border-app-default/30 dark:hover:border-app-default/30 cursor-pointer rounded-[14px] border border-slate-200/80 bg-white p-4 shadow-[0_8px_20px_rgba(15,23,42,0.03)] transition-colors hover:shadow-md dark:border-slate-800 dark:bg-boxdark'
                    : 'rounded-[14px] border border-slate-200/80 bg-white p-4 shadow-[0_8px_20px_rgba(15,23,42,0.03)] dark:border-slate-800 dark:bg-boxdark'
            }
            style={{ opacity: displayDone ? 0.6 : 1 }}
        >
            <div className="flex items-start justify-between gap-3">
                <div className="min-w-0 flex-1">
                    <h4
                        className={`text-sm font-semibold leading-tight text-slate-900 dark:text-slate-100 ${displayDone ? 'line-through opacity-70' : ''}`}
                    >
                        {tarefa.resumo}
                    </h4>
                    <div className="mt-2 flex flex-wrap items-center gap-1.5">
                        <span
                            className={`rounded-sm px-1.5 py-0.5 text-[10px] font-semibold ${statusBadgeClass}`}
                        >
                            {STATUS_LABELS[tarefa.status] ?? tarefa.status}
                        </span>
                        <span
                            className={`rounded-sm px-1.5 py-0.5 text-[10px] font-semibold ${prioBadgeClass}`}
                        >
                            {PRIORIDADE_LABELS[tarefa.prioridade] ?? tarefa.prioridade}
                        </span>
                        {tarefa.prazo_fatal && (
                            <span className="inline-flex items-center gap-1 text-[10px] text-[#888] dark:text-muted-foreground">
                                <Calendar className="h-3 w-3" />
                                {dateFormater(tarefa.prazo_fatal)}
                            </span>
                        )}
                    </div>
                </div>

                <div className="flex shrink-0 items-center gap-2.5">
                    <button
                        type="button"
                        onClick={handleToggleDone}
                        className="h-5.5 w-10 shrink-0 cursor-pointer rounded-full p-0.5 transition-all duration-200 active:scale-95"
                        style={{
                            background: displayDone ? COLORS.green : 'rgba(156, 163, 175, 0.3)',
                        }}
                        title={displayDone ? 'Marcar como pendente' : 'Marcar como concluída'}
                    >
                        <div
                            className="h-4.5 w-4.5 rounded-full bg-white shadow-md transition-transform duration-200"
                            style={{
                                transform: displayDone ? 'translateX(18px)' : 'translateX(0)',
                            }}
                        />
                    </button>

                    {responsavelNome ? (
                        <div
                            className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-[#e5e7eb] text-[10px] font-extrabold text-[#555] dark:bg-muted dark:text-muted-foreground"
                            title={responsavelNome}
                        >
                            {getInitials(responsavelNome)}
                        </div>
                    ) : (
                        <div
                            className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full border border-dashed border-slate-300 text-slate-400 dark:border-slate-700"
                            title="Sem responsável"
                        >
                            <User className="h-3.5 w-3.5" />
                        </div>
                    )}
                    {canOpenCrmPanel && (
                        <Layout className="h-3.5 w-3.5 shrink-0 text-slate-300 dark:text-slate-600" />
                    )}
                </div>
            </div>

            {tarefa.criado_por?.nome && (
                <p className="mt-2 border-t border-dashed border-slate-100 pt-2 text-[10px] text-[#aab0be] dark:border-slate-800 dark:text-muted-foreground">
                    Criada por {tarefa.criado_por.nome} · {dateFormater(tarefa.created_at)}
                </p>
            )}
        </div>
    );
}
